mapper.select:
select count(*) > 0
from subscription_item
where subscription_id = #{subscriptionId}
  and product_source_id = #{productSourceId}
  and plan_version in ('CURRENT', 'NEXT')
  and item_status not in ('CANCELLED')

mapper.delete:
delete from subscription_item
where subscription_item_id = #{subscriptionItemId}
  and plan_version = 'NEXT'

mapper.update:
update subscription
set updated_at = now()
where subscription_id = #{subscriptionId}

mapper.delete:
delete from subscription_item
where subscription_id = #{subscriptionId}
  and plan_version = 'CURRENT'

mapper.update:
update subscription_item
set item_status = #{toStatus},
    updated_at = now()
where subscription_id = #{subscriptionId}
  and plan_version = 'NEXT'
  and item_status = #{fromStatus}

mapper.delete:
delete from subscription_item
where subscription_id = #{subscriptionId}
  and plan_version = 'NEXT'

